    cin.tie(nullptr);

    string seat;
    if (!(cin >> seat)) return 0;

    long long n = 0;
    int i = 0;
    while (i < (int)seat.size() && isdigit(seat[i])) {
        n = n * 10 + (seat[i] - '0');
        ++i;
    }
    char s = seat[i];

    long long row = n;
    long long base = (row - 1) / 4 * 8; // each block of 4 rows takes 8 seconds

    long long ans = base;

    long long posInBlock = (row - 1) % 4; // 0..3

    // For rows 1 and 2 (posInBlock 0,1) the pattern is same as for 3 and 4 (2,3)
    // but offset by 2 rows already counted in base.
    // Determine extra time within the 4-row block.
    // Order of serving rows in a block of 4:
    // row1, row3, row2, row4 (relative indices 0,2,1,3)
    // Each row takes 6 seconds.
    // We compute how many full rows before this row in its block.
    long long fullRowsBefore = 0;
    if (posInBlock == 0) fullRowsBefore = 0;        // row1
    else if (posInBlock == 2) fullRowsBefore = 1;   // row3
    else if (posInBlock == 1) fullRowsBefore = 2;   // row2
    else if (posInBlock == 3) fullRowsBefore = 3;   // row4

    ans += fullRowsBefore * 6;

    // Now add position within the row depending on seat
    // Serving order: f(1), e(2), d(3), c(4), b(5), a(6)
    int add = 0;
    if (s == 'f') add = 1;
    else if (s == 'e') add = 2;
    else if (s == 'd') add = 3;
    else if (s == 'c') add = 4;
    else if (s == 'b') add = 5;
    else if (s == 'a') add = 6;

    ans += add;

    cout << ans << '\n';
    return 0;
}
