int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string seat;
    if (!(cin >> seat)) return 0;

    long long n = 0;
    int i = 0;
    while (i < (int)seat.size() && isdigit(seat[i])) {
        n = n * 10 + (seat[i] - '0');
        ++i;
    }
    char s = seat[i];

    long long row = n;
    long long blocks = (row - 1) / 4;      // each block of 4 rows
    long long ans = blocks * 12;           // 12 seconds per block

    int posInBlock = (row - 1) % 4;        // 0..3
    // rows 1,2,5,6,... (pos 0 or 1) served by first attendant
    // rows 3,4,7,8,... (pos 2 or 3) served by second attendant
    if (posInBlock % 2 == 1) ans += 7;     // second row in pair: +7 seconds

    // seat order in a row:
    // right side: f (1), e (2), d (3)
    // left side:  c (4), b (5), a (6)
    int seatOffset = 0;
    if (s == 'f') seatOffset = 1;
    else if (s == 'e') seatOffset = 2;
    else if (s == 'd') seatOffset = 3;
    else if (s == 'c') seatOffset = 4;
    else if (s == 'b') seatOffset = 5;
    else if (s == 'a') seatOffset = 6;

    ans += seatOffset;

    cout << ans << '\n';
    return 0;
}
